56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        List<String> missingFields = new ArrayList<>();
109	        if (isBlank(ownerFieldsDto.getFirstName())) {
110	            missingFields.add("firstName");
111	        }
112	        if (isBlank(ownerFieldsDto.getLastName())) {
113	            missingFields.add("lastName");
114	        }
115	        if (isBlank(ownerFieldsDto.getAddress())) {
116	            missingFields.add("address");
117	        }
118	        if (isBlank(ownerFieldsDto.getCity())) {
119	            missingFields.add("city");
120	        }
121	        if (isBlank(ownerFieldsDto.getTelephone())) {
122	            missingFields.add("telephone");
123	        }
124	        if (!missingFields.isEmpty()) {
125	            throw new MissingOwnerFieldsException(missingFields);
126	        }
127	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
128	        if (isTelephoneInUse(telephone)) {
129	            throw new DuplicateTelephoneException(ownerFieldsDto.getTelephone());
130	        }
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        if (!sharesHousehold
133	            && isHouseholdInUse(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())) {
134	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
135	        }
136	        HttpHeaders headers = new HttpHeaders();
137	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
138	        owner.setTelephone(telephone);
139	        if (owner.getRegistrationDate() == null) {
140	            owner.setRegistrationDate(LocalDate.now());
141	        }
142	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
143	        if (sharesHousehold) {
144	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
145	        }
146	        this.clinicService.saveOwner(owner);
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Override
155	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
156	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
157	        if (currentOwner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        currentOwner.setAddress(ownerFieldsDto.getAddress());
161	        currentOwner.setCity(ownerFieldsDto.getCity());
162	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
163	        currentOwner.setLastName(ownerFieldsDto.getLastName());
164	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
165	        this.clinicService.saveOwner(currentOwner);
166	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
167	    }
168	
169	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
170	    @Transactional
171	    @Override
172	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
173	        Owner owner = this.clinicService.findOwnerById(ownerId);
174	        if (owner == null) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        this.clinicService.deleteOwner(owner);
178	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        HttpHeaders headers = new HttpHeaders();
189	        Pet pet = petMapper.toPet(petFieldsDto);
190	        owner.setId(ownerId);
191	        pet.setOwner(owner);
192	        pet.getType().setName(null);
193	        this.clinicService.savePet(pet);
194	        PetDto petDto = petMapper.toPetDto(pet);
195	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
196	            .buildAndExpand(pet.getId()).toUri());
197	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
203	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
204	        if (currentOwner != null) {
205	            Pet currentPet = this.clinicService.findPetById(petId);
206	            if (currentPet != null) {
207	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
208	                currentPet.setName(petFieldsDto.getName());
209	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
210	                this.clinicService.savePet(currentPet);
