218	    @Override
219	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
220	        HttpHeaders headers = new HttpHeaders();
221	        Visit visit = visitMapper.toVisit(visitFieldsDto);
222	        Pet pet = new Pet();
223	        pet.setId(petId);
224	        visit.setPet(pet);
225	        this.clinicService.saveVisit(visit);
226	        VisitDto visitDto = visitMapper.toVisitDto(visit);
227	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
228	            .buildAndExpand(visit.getId()).toUri());
229	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
230	    }
231	
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Override
235	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
236	        Owner owner = this.clinicService.findOwnerById(ownerId);
237	        if (owner != null) {
238	            Pet pet = owner.getPet(petId);
239	            if (pet != null) {
240	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
241	            }
242	        }
243	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	    }
245	
246	    private static boolean isBlank(String value) {
247	        return value == null || value.isBlank();
248	    }
249	
250	    /**
251	     * Builds the customer code assigned to a newly created owner. The code is formatted
252	     * {@code <LAST3>-<NNNN>} where {@code LAST3} is the upper-cased first three letters of
253	     * the owner's last name and {@code NNNN} is a global 4-digit zero-padded sequence equal
254	     * to one more than the current number of owners (e.g. {@code SMI-0007}).
255	     *
256	     * @param lastName the last name of the owner being created
257	     * @return the customer code to assign
258	     */
259	    private String nextCustomerCode(String lastName) {
260	        StringBuilder last3 = new StringBuilder();
261	        for (int i = 0; i < lastName.length() && last3.length() < 3; i++) {
262	            char c = lastName.charAt(i);
263	            if (Character.isLetter(c)) {
264	                last3.append(Character.toUpperCase(c));
265	            }
266	        }
267	        long sequence = this.clinicService.findAllOwners().size() + 1L;
268	        return String.format("%s-%04d", last3, sequence);
269	    }
270	
271	    /**
272	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
273	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
274	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
275	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits.
276	     *
277	     * @param rawTelephone the telephone value as supplied by the client
278	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
279	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
280	     */
281	    private static String normalizeTelephone(String rawTelephone) {
282	        if (rawTelephone == null) {
283	            throw new InvalidTelephoneException(rawTelephone);
284	        }
285	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
286	        String e164;
287	        if (cleaned.startsWith("+")) {
288	            String digits = cleaned.substring(1);
289	            if (!digits.matches("[0-9]+")) {
290	                throw new InvalidTelephoneException(rawTelephone);
291	            }
292	            e164 = "+" + digits;
293	        } else {
294	            if (!cleaned.matches("[0-9]+")) {
295	                throw new InvalidTelephoneException(rawTelephone);
296	            }
297	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
298	            e164 = "+61" + national;
299	        }
300	        int digitCount = e164.length() - 1;
301	        if (digitCount < 8 || digitCount > 15) {
302	            throw new InvalidTelephoneException(rawTelephone);
303	        }
304	        return e164;
305	    }
306	
307	    /**
308	     * Determines whether any existing owner already uses the given E.164 telephone. Stored
309	     * telephones are themselves E.164, so the values are compared directly.
310	     *
311	     * @param e164Telephone the E.164 telephone of the owner being created
312	     * @return {@code true} if another owner already has the same E.164 telephone
313	     */
314	    private boolean isTelephoneInUse(String e164Telephone) {
315	        return this.clinicService.findAllOwners().stream()
316	            .map(Owner::getTelephone)
317	            .filter(existing -> existing != null)
318	            .anyMatch(e164Telephone::equals);
319	    }
320	
321	    /**
322	     * Determines whether any existing owner already shares a household with the owner being created,
323	     * i.e. has both the same last name and the same address. Both fields are compared
324	     * case-insensitively after collapsing runs of whitespace to a single space and trimming.
325	     *
326	     * @param lastName the last name of the owner being created
327	     * @param address the address of the owner being created
328	     * @return {@code true} if another owner already has the same last name and address
329	     */
330	    private boolean isHouseholdInUse(String lastName, String address) {
331	        String normalizedLastName = normalizeIdentity(lastName);
332	        String normalizedAddress = normalizeIdentity(address);
333	        return this.clinicService.findAllOwners().stream()
334	            .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
335	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress));
336	    }
337	
338	    /**
339	     * Assigns the owner being created to the household identified by the given last name and
340	     * address and returns the household's stable shared identifier. The identifier is derived
341	     * deterministically from the normalized last name and address, so every member of the same
342	     * household resolves to the same value regardless of creation order. Any existing member that
343	     * does not yet carry the identifier is back-filled so all household members share it.
344	     *
345	     * @param lastName the last name of the owner being created
346	     * @param address the address of the owner being created
347	     * @return the stable household identifier shared by all members of the household
348	     */
349	    private String joinHousehold(String lastName, String address) {
350	        String householdId = householdIdFor(lastName, address);
351	        String normalizedLastName = normalizeIdentity(lastName);
352	        String normalizedAddress = normalizeIdentity(address);
353	        for (Owner existing : this.clinicService.findAllOwners()) {
354	            if (normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
355	                && normalizeIdentity(existing.getAddress()).equals(normalizedAddress)
356	                && !householdId.equals(existing.getHouseholdId())) {
357	                existing.setHouseholdId(householdId);
358	                this.clinicService.saveOwner(existing);
359	            }
360	        }
361	        return householdId;
362	    }
363	
364	    /**
365	     * Derives the stable household identifier for a given last name and address. The value is the
366	     * first 16 upper-case hex characters of the SHA-256 digest of the normalized last name and
367	     * address, so it is stable across calls and identical for every member of the household.
368	     *
369	     * @param lastName the last name of the household
370	     * @param address the address of the household
371	     * @return the stable household identifier
372	     */
373	    private static String householdIdFor(String lastName, String address) {
374	        String key = normalizeIdentity(lastName) + "\n" + normalizeIdentity(address);
375	        try {
376	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
377	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
378	            StringBuilder sb = new StringBuilder(digest.length * 2);
379	            for (byte b : digest) {
380	                sb.append(String.format("%02x", b));
381	            }
382	            return sb.substring(0, 16).toUpperCase(java.util.Locale.ROOT);
383	        }
384	        catch (java.security.NoSuchAlgorithmException e) {
385	            throw new IllegalStateException("SHA-256 not available", e);
386	        }
387	    }
388	
389	    /**
390	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
391	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
392	     * single space, and the result is lower-cased.
393	     *
394	     * @param value the raw field value
395	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
396	     */
397	    private static String normalizeIdentity(String value) {
398	        if (value == null) {
399	            return "";
400	        }
401	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
402	    }
403	}
